// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read request": "in1_Readrequest", "Read budget line": "in2_Readbudgetline", "Read commitments": "in3_Readcommitments"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read commitments";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// The webhook's fields, as the rule reads them in n8n: $('Step 1: Status set to checked; to approval').first().json.body.
DATA["Step 1: Status set to checked; to approval"] = [{ json: { body: { "request_id": input.t_request_id, "version": input.t_version } } }];
const BODIES = (out) => ({"key_q": encodeURIComponent($('Step 1: Status set to checked; to approval').first().json.body.request_id + ':' + $('Step 1: Status set to checked; to approval').first().json.body.version), "approval_body": JSON.stringify(out.approval || {}), "copy_message": (out.approval ? JSON.stringify({ to: $('Config').first().json.budget_owner, subject: 'Over budget: request ' + $('Step 1: Status set to checked; to approval').first().json.body.request_id, text: 'Sent to ' + out.approval.approver + ': ' + out.approval.amount + ' against ' + out.approval.budget_before + ' remaining on ' + out.approval.budget_line }) : null), "stale_body": JSON.stringify({ recipe: 'R11.3', item: $('Step 1: Status set to checked; to approval').first().json.body.request_id, reason: 'budget export stale', detail: out.detail, owner: $('Config').first().json.budget_owner }), "stale_message": JSON.stringify({ to: $('Config').first().json.budget_owner, subject: 'Refresh the budget export', text: out.detail }), "edit_message": JSON.stringify({ to: $('Read request').first().json.requester, subject: 'Request ' + $('Step 1: Status set to checked; to approval').first().json.body.request_id + ' is approved and locked', text: 'Edit refused: this request was approved and released. Raise a new request for the change.' }), "no_approver_body": JSON.stringify({ recipe: 'R11.3', item: $('Step 1: Status set to checked; to approval').first().json.body.request_id, reason: 'no eligible approver', detail: out.detail, owner: $('Config').first().json.senior_approver }), "release_body": JSON.stringify({ p_recipe: 'R11.3', p_key: $('Step 1: Status set to checked; to approval').first().json.body.request_id + ':' + $('Step 1: Status set to checked; to approval').first().json.body.version }), "done_body": JSON.stringify({ status: 'done', result: out.decision }), "log_body": JSON.stringify({ recipe: 'R11.3', item: $('Step 1: Status set to checked; to approval').first().json.body.request_id + ' v' + $('Step 1: Status set to checked; to approval').first().json.body.version, decision: out.decision, rules: out.rules }), "failed_body": JSON.stringify({ recipe: 'R11.3', item: $('Step 1: Status set to checked; to approval').first().json.body.request_id, reason: 'write failed', detail: 'Approval write failed; check the request list, then rerun it', owner: $('Config').first().json.editor })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
const iso = d => d.toISOString().slice(0, 10);
const day = s => new Date(String(s).slice(0, 10) + 'T00:00:00Z');
const today = day(iso(new Date()));
const addWorkingDays = (d, n) => { let x = new Date(d), k = 0; while (k < n) { x = new Date(x.getTime() + 86400000); if (x.getUTCDay() % 6 !== 0) k++; } return x; };
const same = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();

// Steps 3 to 5 of the book's R11.3, in Table 11.2's order.
const cfg = $('Config').first().json;
const ev = $('Step 1: Status set to checked; to approval').first().json.body;
const req = $('Read request').first().json;
const line = $('Read budget line').first().json;
const commitments = $('Read commitments').first().json.items || [];
const amount = Number(req.amount);
const total = Number(req.total != null ? req.total : req.amount);

// Step 10's lock: a released request is never approved again; an edit needs a new request.
if (req.locked) {
  return [{ json: { route: 'edit_refused', decision: 'edit refused; new request needed',
    rules: { locked: true, approved_version: req.approved_version, version: ev.version } } }];
}

// Step 3: remaining budget is budget less spent and committed; an export over the limit waits for the budget owner.
const committed = commitments.reduce((s, c) => s + Number(c.remaining || 0), 0);
const remaining = Number(line.budget) - Number(line.spent) - committed;
const age = line.export_date ? Math.round((today - day(line.export_date)) / 86400000) : null;
const rules = { export_date: line.export_date || null, export_age_days: age, budget: Number(line.budget), spent: Number(line.spent),
  committed, budget_before: remaining, amount, total };
if (age === null || !(age <= cfg.budget_export_max_days)) {
  return [{ json: { route: 'held', decision: 'held: budget export stale', rules,
    detail: `Budget export for ${req.budget_line} is ${age === null ? 'missing' : age + ' days old'}; refresh it, then rerun request ${req.id}` } }];
}

// Step 4: over remaining budget on this request alone (budget owner copied), or over the limit on R11.2's split total, goes to the senior approver.
const overBudget = amount > remaining;
const overLimit = total > cfg.senior_limit;
rules.over_budget = overBudget;
rules.over_limit = overLimit;
const chain = overBudget || overLimit ? [cfg.senior_approver, cfg.approver] : [cfg.approver, cfg.senior_approver];

// Step 5: skip any approver or stand-in who is the requester or the payment approver; the senior approver's own go to the approver.
const barred = p => same(p, req.requester) || same(p, cfg.payment_approver);
const eligible = chain.filter(p => !barred(p));
rules.skipped = chain.filter(barred);
if (!eligible.length) {
  return [{ json: { route: 'no_approver', decision: 'no eligible approver', rules,
    detail: `Every approver and stand-in for request ${req.id} is the requester or the payment approver` } }];
}
const approval = {
  id: `${req.id}-v${ev.version}`, request_id: req.id, version: ev.version, status: 'open',
  approver: eligible[0], standin: eligible[1] || null, requester: req.requester,
  amount, total, valid_until: (req.quote && req.quote.valid_until) || null, waiver: !!req.waiver,
  comparison_link: (req.comparison && req.comparison.link) || null,
  budget_line: req.budget_line, budget_before: remaining, budget_after: remaining - amount,
  created: iso(today),
  remind_on: iso(addWorkingDays(today, cfg.remind_working_days)),
  standin_on: iso(addWorkingDays(today, cfg.standin_working_days)),
};
rules.approver = approval.approver;
rules.standin = approval.standin;
rules.budget_after = approval.budget_after;
return [{ json: { route: 'approval', decision: `sent to ${approval.approver}`, copy_budget_owner: overBudget, approval, rules } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
